import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
} from '@angular/core';
import {
  presentListData,
  presentSetupData,
  presentTeams,
  presentUsers,
} from '../../../interfaces/presentsetup';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';

@Component({
  selector: 'present-teamuser',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, MatCheckboxModule],
  templateUrl: './teamuser.component.html',
  styleUrl: './teamuser.component.scss',
})
export class TeamuserComponent implements OnChanges {
  @Input() presentData: presentSetupData;
  @Input() selectedUser: string[] = [];
  @Output() selectedUserChange = new EventEmitter<string[]>();

  teamUsersList: presentTeams[] = [];

  constructor(
    private readonly present: PresentsetupService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['selectedUser'] && !changes['selectedUser'].firstChange) {
    this.filterSelectedUsers();
    this.checkForDefaultSelected();
    }
  }

  checkForDefaultSelected() {
    try {
      this.teamUsersList.map((a) => {
        a.users?.map((b) => {
          b.isChecked = this.selectedUser.includes(b.nUserid);
        });
      });
      this.teamUsersList.map((a) => {
        a.isChecked = a.users?.every((b) => b.isChecked);
      });
    } catch (error) {
      console.log('error', error);
    }

    this.cdr.detectChanges();
  }

  async ngOnInit() {
    this.teamUsersList = await this.present.getTeam(
      this.presentData.cType,
      this.presentData.nCaseid
    );
    this.checkForDefaultSelected();
    this.cdr.detectChanges();
  }

  onUserSelect(y: presentUsers, x: presentTeams) {
    if (x.users.findIndex((a) => !a.isChecked) > -1) {
      x.isChecked = false;
    } else {
      x.isChecked = true;
    }

    if (y.isChecked) {
      if (!this.selectedUser.includes(y.nUserid))
        this.selectedUser.push(y.nUserid);
    } else {
      const ind = this.selectedUser.findIndex((a) => a == y.nUserid);
      if (ind > -1) this.selectedUser.splice(ind, 1);
    }

    this.selectedUserChange.emit(this.selectedUser);
    this.cdr.detectChanges();
  }

  checkAll(x: presentTeams) {
    //x.users.map((a) => (a.isChecked = x.isChecked));
    x.users.map((a) => {
      a.isChecked = x.isChecked;
      if (x.isChecked) {
        if (!this.selectedUser.includes(a.nUserid)) {
          this.selectedUser.push(a.nUserid);
        }
      } else {
        const ind = this.selectedUser.findIndex((b) => b == a.nUserid);
        if (ind > -1) {
          this.selectedUser.splice(ind, 1);
        }
      }
    });

    this.selectedUserChange.emit(this.selectedUser);

    this.cdr.detectChanges();
  }

  filterSelectedUsers() {
    const allUserIds = this.teamUsersList.flatMap((team) =>
      team.users.map((user) => user.nUserid)
    );
    this.selectedUser = this.selectedUser.filter((userId) =>
      allUserIds.includes(userId)
    );
    this.selectedUserChange.emit(this.selectedUser);
    
    this.cdr.detectChanges();
  }
}
